def __call__(self, tokens: Iterable[Dict[str, Any]], state: BlockState) -> str:
        tokens = list(tokens)
        leading = ""
        i = 0
        while i < len(tokens) and tokens[i]["type"] == "blank_line" and "newlines" in tokens[i]:
            leading += "\n" * tokens[i]["newlines"]
            i += 1
        out = self.render_tokens(tokens[i:], state)
        # special handle for line breaks
        out += "\n\n".join(self.render_referrences(state)) + "\n"
        src = leading + out
        return self._strip_trailing_whitespace(src)

    def _strip_trailing_whitespace(self, src: str) -> str:
        """Strip trailing whitespace after the final line break."""
        end = len(src)
        while end and src[end - 1].isspace():
            end -= 1

        newline = src.find("\n", end)
        if newline >= 0:
            return src[:newline] + "\n"
        return src
