def _ends_with_newline(leaf, suffix=''):
    # Navigate backwards through error leaves with DEDENT type
    while leaf is not None and leaf.type == 'error_leaf' and leaf.token_type == 'DEDENT':
        leaf = leaf.get_previous_leaf()

    # Check if the leaf represents a newline or if suffix ends with newline
    if leaf.type == 'error_leaf':
        leaf_type = leaf.token_type.lower()
    else:
        leaf_type = leaf.type

    return leaf_type == 'newline' or suffix.endswith('\n') or suffix.endswith('\r')
