import codecs
from pygments.util import get_bool_opt
from pygments.util import ClassNotFound
from pygments.styles import _STYLE_NAME_TO_MODULE_MAP
from pygments.plugin import find_plugin_styles

# ...

def _lookup_style(style):
    if isinstance(style, str):
        # Check if it's a builtin style
        if style in _STYLE_NAME_TO_MODULE_MAP:
            mod, cls = _STYLE_NAME_TO_MODULE_MAP[style]
            return _load_style_class(mod, cls, builtin=True)

        # Check if it's a plugin style
        for found_name, style2 in find_plugin_styles():
            if style == found_name:
                return style2

        # Try to load as a custom style
        mod = 'pygments.styles.' + style
        cls = style.title() + 'Style'
        return _load_style_class(mod, cls, builtin=False)

    return style

def _load_style_class(mod, cls, builtin=False):
    """Helper function to load a style class from a module."""
    try:
        mod = __import__(mod, None, None, [cls])
    except ImportError:
        raise ClassNotFound(f'Could not find style module {mod!r}' + (builtin and ', though it should be builtin') + '.')

    try:
        return getattr(mod, cls)
    except AttributeError:
        raise ClassNotFound(f'Could not find style class {cls!r} in style module.')
