        if self.linenos:
            self._write_lineno(outfile)

        for ttype, value in tokensource:
            colors = self._get_colors_for_token(ttype)
            color = colors[self.darkbg] if colors else None

            for line in value.splitlines(True):
                if color:
                    outfile.write(ansiformat(color, line.rstrip('\n')))
                else:
                    outfile.write(line.rstrip('\n'))
                if line.endswith('\n'):
                    if self.linenos:
                        self._write_lineno(outfile)
                    else:
                        outfile.write('\n')

        if self.linenos:
            outfile.write("\n")

    def _get_colors_for_token(self, ttype):
        """Get colors for a token type, traversing parent types if needed."""
        ttype2 = ttype
        colors = self.colorscheme.get(ttype2)
        while colors is None and ttype2.parent:
            ttype2 = ttype2.parent
            colors = self.colorscheme.get(ttype2)
        return colors
