def _align_header(header, alignment, width, visible_width, is_multiline=False, width_fn=None):
    "Pad string header to width chars given known visible_width of the header."
    if is_multiline:
        header_lines = re.split(_multiline_codes, header)
        padded_lines = [_align_header(h, alignment, width, width_fn(h)) for h in header_lines]
        return "\n".join(padded_lines)

    # Calculate the actual width including invisible characters
    ninvisible = len(header) - visible_width
    width += ninvisible

    # Apply alignment based on the alignment parameter
    if alignment == "left":
        return f"{header:<{width}s}"
    elif alignment == "center":
        return _padboth(width, header)
    elif not alignment:
        return header
    else:
        return _padleft(width, header)
