def dissoc(d, *keys, **kwargs):
    """ Return a new dict with the given key(s) removed.

    New dict has d[key] deleted for each supplied key.
    Does not modify the initial dictionary.

    >>> dissoc({'x': 1, 'y': 2}, 'y')
    {'x': 1}
    >>> dissoc({'x': 1, 'y': 2}, 'y', 'x')
    {}
    >>> dissoc({'x': 1}, 'y') # Ignores missing keys
    {'x': 1}
    """
    factory = kwargs.pop('factory', dict)
    if kwargs:
        raise TypeError("{}() got an unexpected keyword argument '{}'".format(dissoc.__name__, kwargs.popitem()[0]))

    # Use the more efficient approach based on the ratio of keys to remove vs total keys
    if len(keys) < len(d) * 0.6:
        # Copy all items and delete the specified keys
        d2 = factory()
        d2.update(d)
        for key in keys:
            d2.pop(key, None)  # pop with default None to ignore missing keys
    else:
        # Create new dict with only the keys we want to keep
        remaining_keys = set(d) - set(keys)
        d2 = factory()
        for key in remaining_keys:
            d2[key] = d[key]

    return d2
